using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages.Evidence; [Authorize] public sealed class EditModel(EvidenceDbContext db, AuditService audit):PageModel { [BindProperty] public EvidenceItem Item {get;set;}=new(); public List<CaseFile> Cases {get;set;}=[]; public async Task<IActionResult> OnGetAsync(int id){var item=await db.Evidence.FindAsync(id);if(item is null)return NotFound();Item=item;Cases=await db.Cases.OrderBy(c=>c.CaseNumber).ToListAsync();return Page();} public async Task<IActionResult> OnPostAsync(){Cases=await db.Cases.OrderBy(c=>c.CaseNumber).ToListAsync();if(!ModelState.IsValid)return Page();var current=await db.Evidence.FindAsync(Item.Id);if(current is null)return NotFound();current.Name=Item.Name;current.Type=Item.Type;current.Status=Item.Status;current.StorageLocation=Item.StorageLocation;current.CollectedOn=Item.CollectedOn;current.CaseFileId=Item.CaseFileId;current.Description=Item.Description;current.SourceDevice=Item.SourceDevice;current.AssociatedPerson=Item.AssociatedPerson;current.CollectionLocation=Item.CollectionLocation;current.Collector=Item.Collector;current.CurrentCustodian=Item.CurrentCustodian;current.Notes=Item.Notes;current.UpdatedAt=DateTime.Now;await db.SaveChangesAsync();await audit.RecordAsync("Evidence updated",$"{current.EvidenceNumber} is now {current.Status}.","Evidence",current.Id.ToString());return RedirectToPage("Index");}}
